mapper.select:
select c.camera_id, c.tree_id, c.category_node_id, coalesce(( select group_concat(distinct tbn.node_name order by tbn.node_id separator '、') from biz_tree_category_bind tcb inner join biz_tree_node tbn on tbn.node_id = tcb.node_id and tbn.del_flag = '0' where tcb.business_type = 'camera' and tcb.business_id = c.camera_id and tcb.del_flag = '0' ), n.node_name) as category_node_name, c.camera_code, c.camera_name, c.sn, c.view_angle, c.manufacturer, c.model_name, c.status, c.create_time, c.remark, case when b.bind_id is null then false else true end as bound, b.vehicle_id as bound_vehicle_id, v.plate_no as bound_plate_no from biz_camera c left join biz_tree_node n on n.node_id = c.category_node_id and n.del_flag = '0' left join biz_vehicle_equipment_bind b on b.equipment_type = '1' and b.equipment_id = c.camera_id and b.del_flag = '0' left join biz_vehicle v on v.id = b.vehicle_id and v.del_flag = 0
c.del_flag = '0'
and c.camera_code like concat('%', #{bo.cameraCode}, '%')
and c.camera_name like concat('%', #{bo.cameraName}, '%')
and c.sn like concat('%', #{bo.sn}, '%')
and c.tree_id = #{bo.treeId}
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'camera' and fcb.business_id = c.camera_id and fcb.del_flag = '0' and fcb.node_id in
#{categoryNodeId}
)
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'camera' and fcb.business_id = c.camera_id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
and c.status = #{bo.status}
order by c.create_time desc, c.camera_id desc

select c.camera_id, c.tree_id, c.category_node_id, coalesce(( select group_concat(distinct tbn.node_name order by tbn.node_id separator '、') from biz_tree_category_bind tcb inner join biz_tree_node tbn on tbn.node_id = tcb.node_id and tbn.del_flag = '0' where tcb.business_type = 'camera' and tcb.business_id = c.camera_id and tcb.del_flag = '0' ), n.node_name) as category_node_name, c.camera_code, c.camera_name, c.sn, c.view_angle, c.manufacturer, c.model_name, c.status, c.create_time, c.remark, case when b.bind_id is null then false else true end as bound, b.vehicle_id as bound_vehicle_id, v.plate_no as bound_plate_no from biz_camera c left join biz_tree_node n on n.node_id = c.category_node_id and n.del_flag = '0' left join biz_vehicle_equipment_bind b on b.equipment_type = '1' and b.equipment_id = c.camera_id and b.del_flag = '0' left join biz_vehicle v on v.id = b.vehicle_id and v.del_flag = 0
c.del_flag = '0'
and c.camera_code like concat('%', #{bo.cameraCode}, '%')
and c.camera_name like concat('%', #{bo.cameraName}, '%')
and c.sn like concat('%', #{bo.sn}, '%')
and c.tree_id = #{bo.treeId}
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'camera' and fcb.business_id = c.camera_id and fcb.del_flag = '0' and fcb.node_id in
#{categoryNodeId}
)
and exists ( select 1 from biz_tree_category_bind fcb where fcb.business_type = 'camera' and fcb.business_id = c.camera_id and fcb.del_flag = '0' and fcb.node_id = #{bo.categoryNodeId} )
and c.status = #{bo.status}
order by c.create_time desc, c.camera_id desc
